SELECT 
FROM S2C_MENU M
WHERE M.MENU_ID = #{menuId}

SELECT COUNT(*)
FROM (
SELECT MENU_ID
FROM S2C_MENU
START WITH MENU_ID = #{rootMenuId}
CONNECT BY NOCYCLE PRIOR MENU_ID = PARENT_MENU_ID
)
WHERE MENU_ID = #{candidateMenuId}

mapper.update:
UPDATE S2C_MENU
SET MENU_LEVEL = MENU_LEVEL + #{levelDelta},
UPDATED_AT = SYSTIMESTAMP,
UPDATED_BY = #{actor}
WHERE MENU_ID IN (
SELECT MENU_ID
FROM S2C_MENU
START WITH MENU_ID = #{menuId}
CONNECT BY NOCYCLE PRIOR MENU_ID = PARENT_MENU_ID
)
AND MENU_ID <> #{menuId}
